import { Policy } from '@nestjs/authorization';
import { AccessService } from '../../../src/iam/access/access.service.js';
import {
  createdBy,
  definePermissions,
  defineSystemJob,
  inMyTeams,
} from '../../../src/iam/access/permissions.js';
import type { Principal } from '../../../src/iam/auth/principal.js';
import { recordPermissionFields } from '../../../src/platform/records/record.js';
import { TEST_ITEM } from './test-item.record.js';
import type { TestItem } from './test-item.schemas.js';
import { testItems } from './test-items.tables.js';

/**
 * A system job that asks for approval on behalf of test items' owners, as
 * the approval engine's tests do outside a request
 * (`system:test-item-publication`).
 */
export const TEST_ITEM_PUBLICATION_JOB = defineSystemJob({
  key: 'test-item-publication',
  label: 'Test item publication',
  description:
    'Publishes test items, or asks for approval first, for their owners.',
  permissions: [{ subject: 'TestItem', action: 'update', conditions: [] }],
});

/**
 * What can be done with test items (the platform's tests' record: test/fixtures),
 * and the conditions an administrator may attach. Generated by
 * `pnpm feature:add`, then a field-level permission (`body`) and the team
 * lead's grant, which the platform's tests read.
 */
export const TEST_ITEM_PERMISSIONS = definePermissions({
  subjects: {
    TestItem: {
      label: 'Test items',
      fields: {
        ...recordPermissionFields(TEST_ITEM),
        body: { label: "The test item's text" },
      },
      conditions: {
        mine: createdBy('ownerId', testItems.ownerId),
        inMyTeams: inMyTeams('teamId', testItems.teamId),
      },
      actions: {
        read: { label: 'See test items', conditions: ['mine', 'inMyTeams'] },
        create: { label: 'Create test items', conditions: [] },
        update: { label: 'Change test items', conditions: ['mine'] },
        delete: { label: 'Delete test items', conditions: ['mine'] },
        restore: {
          label: 'See deleted test items and restore them',
          conditions: ['mine', 'inMyTeams'],
        },
      },
    },
  },
  // What every API client may do, on top of its roles: its own test items.
  clientPermissions: [
    { subject: 'TestItem', action: 'read', conditions: [{ key: 'mine' }] },
    { subject: 'TestItem', action: 'create', conditions: [] },
    { subject: 'TestItem', action: 'update', conditions: [{ key: 'mine' }] },
    { subject: 'TestItem', action: 'delete', conditions: [{ key: 'mine' }] },
    { subject: 'TestItem', action: 'restore', conditions: [{ key: 'mine' }] },
  ],
  // Added to the roles every tenant starts with (same key: merged with the other features').
  seedRoles: [
    {
      key: 'editor',
      name: 'Editor',
      description: 'Writes records and changes their own.',
      permissions: [
        { subject: 'TestItem', action: 'read', conditions: [{ key: 'mine' }] },
        { subject: 'TestItem', action: 'create', conditions: [] },
        {
          subject: 'TestItem',
          action: 'update',
          conditions: [{ key: 'mine' }],
        },
        {
          subject: 'TestItem',
          action: 'delete',
          conditions: [{ key: 'mine' }],
        },
        {
          subject: 'TestItem',
          action: 'restore',
          conditions: [{ key: 'mine' }],
        },
      ],
    },
    {
      key: 'team-lead',
      name: 'Team lead',
      description: 'Sees the records of their teams and every team below them.',
      permissions: [
        {
          subject: 'TestItem',
          action: 'read',
          conditions: [{ key: 'inMyTeams' }],
        },
      ],
    },
    {
      key: 'viewer',
      name: 'Viewer',
      description: 'Sees every record, changes nothing.',
      permissions: [{ subject: 'TestItem', action: 'read', conditions: [] }],
    },
  ],
  systemJobs: [TEST_ITEM_PUBLICATION_JOB],
});

/** The fields of a test item its conditions read. */
type TestItemFields = Pick<TestItem, 'ownerId' | 'teamId' | 'deletedAt'>;
const testItemFields = ({ ownerId, teamId, deletedAt }: TestItemFields) => ({
  ownerId,
  teamId,
  deletedAt,
});

@Policy()
export class TestItemPolicy {
  constructor(private readonly access: AccessService) {}

  create(user: Principal | null) {
    return this.access.can(user, 'create', 'TestItem');
  }

  read(user: Principal | null, testItem: TestItemFields) {
    return this.access.can(user, 'read', 'TestItem', testItemFields(testItem));
  }

  update(user: Principal | null, testItem: TestItemFields) {
    return this.access.can(
      user,
      'update',
      'TestItem',
      testItemFields(testItem),
    );
  }

  delete(user: Principal | null, testItem: TestItemFields) {
    return this.access.can(
      user,
      'delete',
      'TestItem',
      testItemFields(testItem),
    );
  }

  restore(user: Principal | null, testItem: TestItemFields) {
    return this.access.can(
      user,
      'restore',
      'TestItem',
      testItemFields(testItem),
    );
  }
}
